    "exp": "■判断基準■\naは正しく、刃先の向きと周囲を確認して顧客や施術者へ触れないよう扱う。bは刃先を下に向けても開いた刃を顔前で動かすため誤り。cは正しく、姿勢、熱さ、痛みなどを必要に応じて確認する。dは不快感の把握を顧客の申出だけに委ねており誤り\n\n■根拠■\n皮膚状態と毛流を確認し、皮膚を適度に緊張させ、刃角・刃圧・ストロークを部位に応じて調整する。器具と布片類の衛生管理を併せて判断する\n厚生労働省「理容師養成施設の教科課程の基準の運用について」\nhttps://www.mhlw.go.jp/content/11130500/001403710.pdf\n厚生労働省「理容師養成施設の教科課程の基準の運用について」\nhttps://www.mhlw.go.jp/web/t_doc?dataId=00tc1044&dataType=1&pageNo=1\n公益財団法人理容師美容師試験研修センター「過去の筆記試験問題」\nhttps://www.rbc.or.jp/exam/past_question/\n\n■注意点■\n順剃りと逆剃り、刃角と刃圧、鼻下と首部、皮膚緊張と強い牽引を取り違えない",
